import React, { useEffect, useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import api from '../../api/axios';

export default function PageAlertes() {
  const { user }  = useAuth();
  const [alertes, setAlertes]   = useState([]);
  const [loading, setLoading]   = useState(true);
  const [filtre, setFiltre]     = useState('TOUS');

  useEffect(() => { fetchAlertes(); }, []);

  const fetchAlertes = () => {
    api.get('/alertes').then(r => {
      setAlertes(r.data);
      setLoading(false);
    });
  };

 const acquitter = async (id) => {
  try {
    await api.post(`/alertes/${id}/acquitter`, { utilisateur_id: user?.id });
    setAlertes(prev => prev.map(a =>
      a.id === id ? { ...a, acquittee: 1 } : a
    ));
  } catch(e) {
    console.error('Erreur acquittement:', e.response?.data);
    alert(e.response?.data?.message || 'Erreur : ' + e.message);
  }
};

  const acquitterTout = async () => {
    if (!window.confirm('Acquitter toutes les alertes actives ?')) return;
    const actives = alertes.filter(a => !a.acquittee);
    await Promise.all(actives.map(a =>
      api.post(`/alertes/${a.id}/acquitter`, { utilisateur_id: user?.id })
    ));
    setAlertes(prev => prev.map(a => ({ ...a, acquittee: 1 })));
  };

  const filtrees = alertes.filter(a => {
    if (filtre === 'TOUS')      return true;
    if (filtre === 'ACTIVES')   return !a.acquittee;
    if (filtre === 'ACQUITTEES') return a.acquittee;
    return a.niveau === filtre;
  });

  const critique = alertes.filter(a => a.niveau === 'CRITIQUE' && !a.acquittee).length;
  const warning  = alertes.filter(a => a.niveau === 'WARNING'  && !a.acquittee).length;
  const actives  = alertes.filter(a => !a.acquittee).length;

  const niveauStyle = {
    CRITIQUE: { background:'rgba(255,71,87,0.15)',  color:'#ff4757', border:'1px solid rgba(255,71,87,0.25)' },
    WARNING:  { background:'rgba(245,166,35,0.15)', color:'#f5a623', border:'1px solid rgba(245,166,35,0.25)' },
    INFO:     { background:'rgba(0,153,255,0.15)',  color:'#0099ff', border:'1px solid rgba(0,153,255,0.25)' },
  };

  const niveauDot = {
    CRITIQUE: '#ff4757',
    WARNING:  '#f5a623',
    INFO:     '#0099ff',
  };

  if (loading) return <div style={S.loading}>Chargement...</div>;

  return (
    <div>
      {/* Métriques */}
      <div style={S.metricsRow}>
        <div style={S.mcard}>
          <div style={{...S.mcardBar, background:'#ff4757'}}/>
          <div style={S.mcardLabel}>CRITIQUES ACTIVES</div>
          <div style={S.mcardVal}>{critique}</div>
          <div style={S.mcardStatus}>
            <span style={{...S.dot, background: critique > 0 ? '#ff4757' : '#2ed573'}}/>
            <span style={{fontSize:11, color: critique > 0 ? '#ff4757' : '#2ed573'}}>
              {critique > 0 ? 'Action requise' : 'Aucune'}
            </span>
          </div>
        </div>
        <div style={S.mcard}>
          <div style={{...S.mcardBar, background:'#f5a623'}}/>
          <div style={S.mcardLabel}>WARNINGS ACTIFS</div>
          <div style={S.mcardVal}>{warning}</div>
          <div style={S.mcardStatus}>
            <span style={{...S.dot, background: warning > 0 ? '#f5a623' : '#2ed573'}}/>
            <span style={{fontSize:11, color: warning > 0 ? '#f5a623' : '#2ed573'}}>
              {warning > 0 ? 'À surveiller' : 'Aucun'}
            </span>
          </div>
        </div>
        <div style={S.mcard}>
          <div style={{...S.mcardBar, background:'#0099ff'}}/>
          <div style={S.mcardLabel}>TOTAL NON ACQUITTÉES</div>
          <div style={S.mcardVal}>{actives}</div>
          <div style={S.mcardStatus}>
            <span style={{...S.dot, background: actives > 0 ? '#0099ff' : '#2ed573'}}/>
            <span style={{fontSize:11, color:'#7a8394'}}>sur {alertes.length} alertes</span>
          </div>
        </div>
        <div style={S.mcard}>
          <div style={{...S.mcardBar, background:'#2ed573'}}/>
          <div style={S.mcardLabel}>ACQUITTÉES</div>
          <div style={S.mcardVal}>{alertes.length - actives}</div>
          <div style={S.mcardStatus}>
            <span style={{...S.dot, background:'#2ed573'}}/>
            <span style={{fontSize:11, color:'#2ed573'}}>Traitées</span>
          </div>
        </div>
      </div>

      {/* Filtres + bouton acquitter tout */}
      <div style={S.toolbar}>
        <div style={S.filtres}>
          {['TOUS', 'ACTIVES', 'CRITIQUE', 'WARNING', 'ACQUITTEES'].map(f => (
            <button
              key={f}
              style={{...S.filtreBtn, ...(filtre===f ? S.filtreBtnActive : {})}}
              onClick={() => setFiltre(f)}
            >
              {f}
            </button>
          ))}
        </div>
        {actives > 0 && user?.role !== 'operateur' && (
          <button style={S.btnAcquitterTout} onClick={acquitterTout}>
            ✓ Acquitter tout ({actives})
          </button>
        )}
      </div>

      {/* Liste alertes */}
      <div style={S.card}>
        {filtrees.length === 0 ? (
          <div style={S.empty}>Aucune alerte trouvée</div>
        ) : (
          filtrees.map(a => (
            <div key={a.id} style={{...S.alertItem, opacity: a.acquittee ? 0.45 : 1}}>
              {/* Dot niveau */}
              <div style={{...S.alertDot, background: niveauDot[a.niveau] || '#7a8394',
                boxShadow: !a.acquittee && a.niveau==='CRITIQUE' ? `0 0 8px ${niveauDot[a.niveau]}` : 'none'
              }}/>

              {/* Contenu */}
              <div style={{flex:1}}>
                <div style={S.alertMsg}>{a.message}</div>
                <div style={S.alertMeta}>
                  <span style={{...S.pill, ...niveauStyle[a.niveau]}}>{a.niveau}</span>
                  {a.valeur && (
                    <span style={S.alertVal}>
                      Valeur : <strong>{parseFloat(a.valeur).toFixed(2)}</strong>
                      {a.seuil && <> / Seuil : <strong>{parseFloat(a.seuil).toFixed(2)}</strong></>}
                    </span>
                  )}
                  <span style={S.alertTime}>
                    {new Date(a.cree_le).toLocaleString('fr-FR')}
                  </span>
                </div>
              </div>

              {/* Bouton acquitter */}
              {!a.acquittee ? (
                user?.role !== 'operateur' ? (
                  <button style={S.btnAcquitter} onClick={() => acquitter(a.id)}>
                    Acquitter
                  </button>
                ) : (
                  <span style={S.nonAcquittee}>En attente</span>
                )
              ) : (
                <span style={S.acquittee}>✓ Acquittée</span>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
}

const S = {
  loading:         { color:'#7a8394', textAlign:'center', marginTop:40 },
  metricsRow:      { display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:14, marginBottom:20 },
  mcard:           { background:'#161b22', border:'1px solid rgba(255,255,255,0.07)', borderRadius:10, padding:'18px 20px', position:'relative', overflow:'hidden' },
  mcardBar:        { position:'absolute', top:0, left:0, right:0, height:2 },
  mcardLabel:      { fontFamily:'monospace', fontSize:10, color:'#4a5260', letterSpacing:1.5, textTransform:'uppercase', marginBottom:12 },
  mcardVal:        { fontSize:28, fontWeight:600, color:'#e8eaf0', fontFamily:'monospace' },
  mcardStatus:     { display:'flex', alignItems:'center', gap:5, marginTop:8 },
  dot:             { width:5, height:5, borderRadius:'50%', flexShrink:0 },
  toolbar:         { display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:16 },
  filtres:         { display:'flex', gap:8 },
  filtreBtn:       { padding:'6px 12px', background:'transparent', border:'1px solid rgba(255,255,255,0.10)', borderRadius:6, color:'#7a8394', fontSize:11, cursor:'pointer', fontFamily:'monospace' },
  filtreBtnActive: { background:'rgba(0,212,170,0.10)', borderColor:'rgba(0,212,170,0.30)', color:'#00d4aa' },
  btnAcquitterTout:{ padding:'7px 14px', background:'rgba(46,213,115,0.10)', border:'1px solid rgba(46,213,115,0.25)', borderRadius:7, color:'#2ed573', fontSize:12, cursor:'pointer', fontFamily:'monospace' },
  card:            { background:'#161b22', border:'1px solid rgba(255,255,255,0.07)', borderRadius:10, padding:'20px 22px' },
  empty:           { color:'#7a8394', textAlign:'center', padding:'40px 0', fontSize:13 },
  alertItem:       { display:'flex', alignItems:'center', gap:14, padding:'16px 0', borderBottom:'1px solid rgba(255,255,255,0.05)', transition:'opacity 0.3s' },
  alertDot:        { width:8, height:8, borderRadius:'50%', flexShrink:0 },
  alertMsg:        { fontSize:13, color:'#e8eaf0', marginBottom:8, fontWeight:500 },
  alertMeta:       { display:'flex', alignItems:'center', gap:12, flexWrap:'wrap' },
  alertVal:        { fontSize:11, color:'#7a8394', fontFamily:'monospace' },
  alertTime:       { fontSize:11, color:'#4a5260', fontFamily:'monospace' },
  pill:            { display:'inline-flex', fontFamily:'monospace', fontSize:10, padding:'3px 8px', borderRadius:4 },
  btnAcquitter:    { padding:'6px 14px', background:'rgba(0,212,170,0.10)', border:'1px solid rgba(0,212,170,0.25)', borderRadius:6, color:'#00d4aa', fontSize:12, cursor:'pointer', flexShrink:0, fontFamily:'monospace' },
  acquittee:       { fontSize:11, color:'#2ed573', fontFamily:'monospace', flexShrink:0 },
  nonAcquittee:    { fontSize:11, color:'#f5a623', fontFamily:'monospace', flexShrink:0 },
};
